import { isValidCPF } from 'cpf-validator';

export function validateCPF(cpf: string): boolean {
  return isValidCPF(cpf);
}

import { validateCPF } from '../validators/cpf';

export async function createUser(data: UserData) {
  if (!validateCPF(data.cpf)) {
    throw new Error('CPF inválido');
  }
  return await userRepository.save(data);
}

export class PagSeguroClient {
  async createTransaction(data: TransactionData) {
    const response = await fetch('https://api.pagseguro.com/v1/transactions', {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${process.env.PAGSEGURO_TOKEN}` },
      body: JSON.stringify(data)
    });
    return response.json();
  }

  async refundTransaction(id: string) {
    const response = await fetch(`https://api.pagseguro.com/v1/transactions/${id}/refund`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${process.env.PAGSEGURO_TOKEN}` }
    });
    return response.json();
  }
}

import { PagSeguroClient } from './pagseguro/client';

const client = new PagSeguroClient();

export async function processPayment(data: PaymentData) {
  try {
    const result = await client.createTransaction(data);
    return { success: true, transactionId: result.id };
  } catch (error) {
    return { success: false, error: error.message };
  }
}

import Redis from 'ioredis';

const redis = new Redis(process.env.REDIS_URL);

export async function getCached<T>(key: string): Promise<T | null> {
  const data = await redis.get(key);
  return data ? JSON.parse(data) : null;
}

export async function setCached(key: string, value: any, ttl: number): Promise<void> {
  await redis.setex(key, ttl, JSON.stringify(value));
}

import { getCached, setCached } from '../cache/redis';

export async function getDashboardMetrics(userId: string) {
  const cacheKey = `dashboard:${userId}`;
  const cached = await getCached(cacheKey);

  if (cached) {
    return cached;
  }

  const metrics = await calculateMetrics(userId);
  await setCached(cacheKey, metrics, 300);
  return metrics;
}

export class DatabaseConnection {
  private static instance: DatabaseConnection;
  private connection: any;

  private constructor() {
    this.connection = createConnection();
  }

  public static getInstance(): DatabaseConnection {
    if (!DatabaseConnection.instance) {
      DatabaseConnection.instance = new DatabaseConnection();
    }
    return DatabaseConnection.instance;
  }

  async query(sql: string, params: any[]) {
    return this.connection.query(sql, params);
  }

  async transaction(callback: Function) {
    const trx = await this.connection.beginTransaction();
    try {
      await callback(trx);
      await this.connection.commit(trx);
    } catch (error) {
      await this.connection.rollback(trx);
      throw error;
    }
  }
}

export const db = DatabaseConnection.getInstance();

